<?php declare(strict_types=1); namespace App\People\Domain\Model; use App\People\Domain\Enum\Gender; use App\People\Domain\Enum\MembershipStatus; use App\People\Domain\Event\PersonRegistered; use App\People\Domain\ValueObject\EmailAddress; use App\People\Domain\ValueObject\PersonId; use App\People\Domain\ValueObject\PersonName; use App\People\Domain\ValueObject\PhoneNumber; use App\Shared\Domain\Event\DomainEvent; use App\Shared\Domain\ValueObject\AuditTimestamps; final class Person {private array $domainEvents=[]; private function __construct(private readonly PersonId $id,private PersonName $name,private ?\DateTimeImmutable $dateOfBirth,private Gender $gender,private ?EmailAddress $email,private ?PhoneNumber $phone,private MembershipStatus $status,private readonly AuditTimestamps $audit){} public static function register(PersonId $id,PersonName $name,?\DateTimeImmutable $dob,Gender $gender,?EmailAddress $email,?PhoneNumber $phone,\DateTimeImmutable $now):self{$p=new self($id,$name,$dob,$gender,$email,$phone,MembershipStatus::PROSPECT,new AuditTimestamps($now,$now));$p->domainEvents[]=new PersonRegistered($id->toString(),$now);return $p;} public static function reconstitute(PersonId $id,PersonName $name,?\DateTimeImmutable $dob,Gender $gender,?EmailAddress $email,?PhoneNumber $phone,MembershipStatus $status,AuditTimestamps $audit):self{return new self($id,$name,$dob,$gender,$email,$phone,$status,$audit);} public function id():PersonId{return $this->id;} public function name():PersonName{return $this->name;} public function dateOfBirth():?\DateTimeImmutable{return $this->dateOfBirth;} public function gender():Gender{return $this->gender;} public function email():?EmailAddress{return $this->email;} public function phone():?PhoneNumber{return $this->phone;} public function status():MembershipStatus{return $this->status;} public function createdAt():\DateTimeImmutable{return $this->audit->createdAt();} public function updatedAt():\DateTimeImmutable{return $this->audit->updatedAt();} public function update(PersonName $name,?\DateTimeImmutable $dob,Gender $gender,?EmailAddress $email,?PhoneNumber $phone,\DateTimeImmutable $now):void{$this->name=$name;$this->dateOfBirth=$dob;$this->gender=$gender;$this->email=$email;$this->phone=$phone;$this->audit->touch($now);} public function changeStatus(MembershipStatus $status,\DateTimeImmutable $now):void{if($this->status!==$status){$this->status=$status;$this->audit->touch($now);}} public function releaseDomainEvents():array{$e=$this->domainEvents;$this->domainEvents=[];return $e;} }
